            const imageCard = deleteBtn.closest('.image-card');
            if (imageCard) {
                // Add fade-out animation
                imageCard.style.opacity = '0';
                imageCard.style.transition = 'opacity 0.3s ease-out';

                setTimeout(() => {
                    imageCard.remove();

                    // Show a success message (optional)
                    this.showSuccessMessage('Image deleted successfully');

                    // Close the dialog and restore focus
                    this.closeDialog();
                }, 300);
                return;
            }
        }

        this.closeDialog();
    }

    showSuccessMessage(message) {
        // Create a temporary success notification
        const notification = document.createElement('div');
        notification.setAttribute('role', 'status');
        notification.setAttribute('aria-live', 'polite');
        notification.className = 'success-notification';
        notification.textContent = message;

        document.body.appendChild(notification);

        // Show for 3 seconds then remove
        setTimeout(() => {
            notification.style.opacity = '1';
        }, 10);

        setTimeout(() => {
            notification.style.opacity = '0';
            setTimeout(() => notification.remove(), 300);
        }, 3000);
    }
