const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const axe = require('axe-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.resolve(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  // Wait a bit for styles to load
  await page.waitForTimeout(100);

  // Inject axe
  await page.addScriptTag({ content: axe.source });

  // Run axe
  const results = await page.evaluate(() => window.axe.run());

  await browser.close();

  // Separate WCAG violations from best-practice
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  const output = {
    wcag: wcag.map(v => ({
      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  };

