const fs = require('fs');
const path = require('path');
const axe = require('axe-core');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlPath = path.resolve(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlPath, 'utf8');

  await page.setContent(htmlContent, { waitUntil: 'domcontentloaded' });

  // Wait for JS to execute
  await page.waitForFunction(() => {
    return window.DeleteConfirmDialog !== undefined;
  }, { timeout: 5000 }).catch(() => {
    console.log('Warning: DeleteConfirmDialog not loaded');
  });

  await page.waitForTimeout(200);

  // Inject axe
  await page.addScriptTag({ content: require('axe-core').source });

  console.log('=== Test 1: Initial Page State ===');
  let results = await page.evaluate(() => window.axe.run());
  let wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  let bp = results.violations.filter(v => v.tags.includes('best-practice'));

  if (wcag.length === 0 && bp.length === 0) {
    console.log('✓ PASS - No violations');
  } else {
    console.log('Violations found:');
    wcag.forEach(v => console.log(`  WCAG [${v.impact}] ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`));
    bp.forEach(v => console.log(`  BP ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`));
  }

  console.log('\n=== Test 2: Dialog Open State ===');
  // Open the dialog by clicking the first delete button
  await page.click('button.delete-btn[data-image-id="img-1"]');
  await page.waitForTimeout(500);

  // Check if dialog is open
  const isOpen = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    return dialog ? dialog.open : false;
  });
  console.log('Dialog open:', isOpen);

  // Run axe on dialog state
  results = await page.evaluate(() => window.axe.run());
  wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  bp = results.violations.filter(v => v.tags.includes('best-practice'));

  if (wcag.length === 0 && bp.length === 0) {
    console.log('✓ PASS - No violations in dialog state');
  } else {
    console.log('Violations found:');
    wcag.forEach(v => console.log(`  WCAG [${v.impact}] ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`));
    bp.forEach(v => console.log(`  BP ${v.id}: ${v.nodes.map(n => n.target).join(', ')}`));
  }

  console.log('\n=== Test 3: Dialog Content Accessibility ===');
  // Check focus position
  const focusedElement = await page.evaluate(() => {
    const focused = document.activeElement;
    if (focused && focused.tagName === 'BUTTON') {
      return focused.getAttribute('data-action');
    }
    return null;
  });
  console.log('Focused element:', focusedElement || 'none');
  console.log('Focus should be on cancel button:', focusedElement === 'cancel' ? '✓' : '⚠');

  // Check dialog has proper labeling
  const labelingCheck = await page.evaluate(() => {
    const dialog = document.getElementById('delete-confirm-dialog');
    const hasLabelledBy = dialog.getAttribute('aria-labelledby') !== null;
    const hasDescribedBy = dialog.getAttribute('aria-describedby') !== null;
    const heading = document.getElementById('delete-dialog-heading');
    const description = document.getElementById('delete-dialog-body');
    return {
      hasLabelledBy,
      hasDescribedBy,
      headingExists: heading !== null,
      descriptionExists: description !== null
    };
  });
  console.log('Dialog labeling:', JSON.stringify(labelingCheck));

  // Run final axe check
  results = await page.evaluate(() => window.axe.run());
  wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log('\n=== Summary ===');
  if (wcag.length === 0 && bp.length === 0) {
    console.log('✓✓✓ ALL TESTS PASSED ✓✓✓');
  }

  await browser.close();
  process.exit(wcag.length > 0 ? 1 : 0);
})();
